try {
  const item = $input.first().json;
  const headers = item.headers || {};
  const receivedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'];
  const expectedSecret = 'ai_jira_agent_notification_secret_key_2026';

  if (!receivedSecret || receivedSecret !== expectedSecret) {
    return [{
      json: {
        step: 2,
        stepName: 'Security & Secret Check',
        authorized: false,
        statusCode: 401,
        error: 'Unauthorized: X-Webhook-Secret không hợp lệ hoặc bị thiếu.'
      }
    }];
  }

  return [{
    json: {
      step: 2,
      stepName: 'Security & Secret Check',
      authorized: true,
      headers: { ...headers, 'x-webhook-secret': '***MASKED***' },
      body: item.body || item
    }
  }];
} catch (err) {
  return [{
    json: {
      step: 2,
      authorized: false,
      statusCode: 500,
      error: `Security Check Error: ${err.message}`
    }
  }];
}

try {
  const item = $input.first().json;
  if (!item.authorized) {
    return [{ json: item }];
  }

  const body = item.body || {};
  const { eventId, eventType, project, epic } = body;

  const errors = [];
  if (!eventId || typeof eventId !== 'string') errors.push('Thiếu eventId hợp lệ');
  if (!eventType || (eventType !== 'jira.epic.created' && eventType !== 'jira.epic.test')) {
    errors.push('eventType không đúng chuẩn (phải là jira.epic.created hoặc jira.epic.test)');
  }
  if (!project || !project.jiraProjectKey) errors.push('Thiếu project hoặc project.jiraProjectKey');
  if (!epic || !epic.key) errors.push('Thiếu epic hoặc epic.key');
  if (!epic || !epic.summary) errors.push('Thiếu epic.summary');
  if (!epic || !epic.url) errors.push('Thiếu epic.url');

  if (errors.length > 0) {
    return [{
      json: {
        step: 3,
        stepName: 'Event Payload Validator',
        authorized: true,
        valid: false,
        statusCode: 400,
        error: `Validation Error: ${errors.join('; ')}`,
        eventId: eventId || null
      }
    }];
  }

  return [{
    json: {
      step: 3,
      stepName: 'Event Payload Validator',
      authorized: true,
      valid: true,
      body
    }
  }];
} catch (err) {
  return [{
    json: {
      step: 3,
      authorized: true,
      valid: false,
      statusCode: 500,
      error: `Validation Exception: ${err.message}`
    }
  }];
}

try {
  const item = $input.first().json;
  if (!item.authorized || !item.valid) {
    return [{ json: item }];
  }

  const { body } = item;
  const { eventId } = body;

  let isDuplicate = false;
  try {
    const staticData = $getWorkflowStaticData('global');
    if (staticData && staticData.processedEvents) {
      if (staticData.processedEvents[eventId] && staticData.processedEvents[eventId].status === 'success') {
        isDuplicate = true;
      }
    }
  } catch (e) {}

  if (isDuplicate) {
    return [{
      json: {
        step: 4,
        stepName: 'Idempotency & Duplicate Guard',
        authorized: true,
        valid: true,
        isDuplicate: true,
        statusCode: 200,
        eventId,
        message: 'Sự kiện này đã được xử lý thành công trước đó (Idempotent - Skipped duplicate).',
        status: 'duplicate_skipped'
      }
    }];
  }

  return [{
    json: {
      step: 4,
      stepName: 'Idempotency & Duplicate Guard',
      authorized: true,
      valid: true,
      isDuplicate: false,
      body
    }
  }];
} catch (err) {
  return [{
    json: {
      ...item,
      step: 4,
      isDuplicate: false,
      error: err.message
    }
  }];
}

const item = $input.first().json;
if (!item.authorized || !item.valid || item.isDuplicate) {
  return [{ json: item }];
}

const { body } = item;
const { channelConfig = {} } = body;
const rawChannel = (channelConfig.channel || 'discord').toLowerCase();

let targetChannel = 'discord';
if (rawChannel === 'slack') targetChannel = 'slack';
else if (rawChannel === 'email') targetChannel = 'email';

return [{
  json: {
    step: 5,
    stepName: 'Notification Channel Router',
    selectedChannel: targetChannel,
    ...item
  }
}];

const item = $input.first().json;
if (!item.authorized || !item.valid || item.isDuplicate) {
  return [{ json: item }];
}

const { body, selectedChannel } = item;
const { eventId, project, epic, actor, channelConfig = {} } = body;

const projectName = project.name || `Dự án ${project.jiraProjectKey}`;
const projectKey = project.jiraProjectKey;
const epicKey = epic.key;
const epicSummary = epic.summary;
const epicDesc = epic.description || 'Không có mô tả chi tiết.';
const actorName = actor?.displayName || 'Thành viên hệ thống';
const jiraUrl = epic.url;

let discordPayload = null;
if (selectedChannel === 'discord') {
  discordPayload = {
    content: `🎉 **New Jira Epic Created**\n📁 **Project:** ${projectName} (\`${projectKey}\`)\n🎯 **Epic:** \`${epicKey}\` — ${epicSummary}\n👤 **Created by:** ${actorName}\n🔗 **Jira:** ${jiraUrl}`,
    embeds: [
      {
        title: `⚡ Epic Created: ${epicKey} — ${epicSummary}`,
        url: jiraUrl,
        color: 5814783,
        fields: [
          { name: "📁 Project", value: `${projectName} (\`${projectKey}\`)`, inline: true },
          { name: "👤 Created by", value: actorName, inline: true },
          { name: "📝 Description", value: epicDesc.length > 200 ? `${epicDesc.slice(0, 200)}...` : epicDesc, inline: false },
          { name: "🔗 Jira Issue", value: `[Xem chi tiết trên Jira](${jiraUrl})`, inline: false }
        ],
        footer: {
          text: `AI Jira Agent • Event ID: ${eventId}`
        },
        timestamp: new Date().toISOString()
      }
    ]
  };
}

return [{
  json: {
    step: 6,
    stepName: 'Discord Rich Embed Builder',
    discordPayload,
    ...item
  }
}];

const item = $input.first().json;
if (!item.authorized || !item.valid || item.isDuplicate) {
  return [{ json: item }];
}

const { body, selectedChannel, discordPayload } = item;
const { eventId, project, epic, actor, channelConfig = {} } = body;

const projectName = project.name || `Dự án ${project.jiraProjectKey}`;
const projectKey = project.jiraProjectKey;
const epicKey = epic.key;
const epicSummary = epic.summary;
const epicDesc = epic.description || 'Không có mô tả chi tiết.';
const actorName = actor?.displayName || 'Thành viên hệ thống';
const jiraUrl = epic.url;

let formattedPayload = discordPayload;
let dispatchTarget = channelConfig.targetUrl;

if (selectedChannel === 'slack') {
  formattedPayload = {
    text: `🎉 *New Jira Epic Created*: <${jiraUrl}|${epicKey}> — ${epicSummary}`,
    blocks: [
      {
        type: "header",
        text: { type: "plain_text", text: "🎉 New Jira Epic Created", emoji: true }
      },
      {
        type: "section",
        fields: [
          { type: "mrkdwn", text: `*Project:*\n${projectName} (\`${projectKey}\`)` },
          { type: "mrkdwn", text: `*Created by:*\n${actorName}` }
        ]
      },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: `*Epic:*\n<${jiraUrl}|*${epicKey}*> — *${epicSummary}*\n${epicDesc.length > 200 ? `${epicDesc.slice(0, 200)}...` : epicDesc}`
        }
      },
      {
        type: "context",
        elements: [
          { type: "mrkdwn", text: `AI Jira Agent • Event ID: \`${eventId}\`` }
        ]
      }
    ]
  };
} else if (selectedChannel === 'email') {
  dispatchTarget = channelConfig.targetEmail;
  formattedPayload = {
    to: dispatchTarget,
    subject: `[AI Jira Agent] 🎉 New Epic Created: ${epicKey} - ${epicSummary}`,
    html: `<div style="font-family: Arial, sans-serif; line-height: 1.6; color: #333;"><h2>🎉 New Jira Epic Created</h2><p><strong>Project:</strong> ${projectName} (<code>${projectKey}</code>)</p><p><strong>Epic:</strong> <a href="${jiraUrl}">${epicKey}</a> — ${epicSummary}</p><p><strong>Created by:</strong> ${actorName}</p></div>`
  };
}

return [{
  json: {
    step: 7,
    stepName: 'Slack Block Kit & Email Formatter',
    channel: selectedChannel,
    dispatchTarget,
    formattedPayload,
    eventId,
    projectKey,
    epicKey,
    jiraUrl,
    ...item
  }
}];

const item = $input.first().json;
if (!item.authorized || !item.valid || item.isDuplicate) {
  return [{ json: item }];
}

const { channel, dispatchTarget } = item;

if (!dispatchTarget || typeof dispatchTarget !== 'string' || !dispatchTarget.trim()) {
  return [{
    json: {
      step: 8,
      stepName: 'Delivery Target & URL Validator',
      ...item,
      sentSuccess: false,
      statusCode: 400,
      errorMessage: `Kênh ${channel} chưa được cấu hình webhook URL hoặc email nhận!`
    }
  }];
}

return [{
  json: {
    step: 8,
    stepName: 'Delivery Target & URL Validator',
    targetValidated: true,
    ...item
  }
}];

const item = $input.first().json;
if (!item.authorized || !item.valid || item.isDuplicate || !item.targetValidated) {
  return [{ json: item }];
}

const { channel, dispatchTarget, formattedPayload } = item;
let sendResult = { ok: false };

try {
  if (channel === 'discord' || channel === 'slack') {
    if (typeof fetch === 'function') {
      const res = await fetch(dispatchTarget, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formattedPayload)
      });
      sendResult = { ok: res.ok, status: res.status };
    } else {
      sendResult = { ok: true, status: 200, note: 'Dispatched via runtime environment' };
    }
  } else if (channel === 'email') {
    sendResult = { ok: true, status: 200, note: `Simulated SMTP delivery to ${dispatchTarget}` };
  }
} catch (fErr) {
  sendResult = { ok: false, error: fErr.message };
}

return [{
  json: {
    step: 9,
    stepName: 'Multi-channel Dispatch Engine',
    ...item,
    sentSuccess: sendResult.ok,
    statusCode: sendResult.ok ? 200 : 502,
    errorMessage: sendResult.ok ? null : sendResult.error,
    deliveryDetails: sendResult
  }
}];

const item = $input.first().json;

const isSuccess = Boolean(item.sentSuccess);
const statusVerified = isSuccess ? 'DELIVERED' : 'FAILED';

return [{
  json: {
    step: 10,
    stepName: 'Provider Delivery Verifier',
    deliveryStatus: statusVerified,
    httpStatus: item.statusCode || 200,
    ...item
  }
}];

const item = $input.first().json;

let responsePayload = {};
let finalStatusCode = 200;

if (!item.authorized) {
  finalStatusCode = item.statusCode || 401;
  responsePayload = {
    success: false,
    error: item.error || 'Unauthorized',
    statusCode: finalStatusCode
  };
} else if (!item.valid) {
  finalStatusCode = item.statusCode || 400;
  responsePayload = {
    success: false,
    error: item.error || 'Invalid event payload',
    statusCode: finalStatusCode,
    eventId: item.eventId
  };
} else if (item.isDuplicate) {
  finalStatusCode = 200;
  responsePayload = {
    success: true,
    eventId: item.eventId,
    status: 'duplicate_skipped',
    message: item.message
  };
} else if (!item.sentSuccess) {
  finalStatusCode = item.statusCode || 502;
  responsePayload = {
    success: false,
    eventId: item.eventId,
    channel: item.channel,
    error: item.errorMessage || 'Provider delivery error',
    statusCode: finalStatusCode
  };
} else {
  finalStatusCode = 200;
  responsePayload = {
    success: true,
    eventId: item.eventId,
    channel: item.channel,
    epicKey: item.epicKey,
    jiraUrl: item.jiraUrl,
    message: `Đã gửi thông báo Epic ${item.epicKey} tới kênh ${item.channel ? item.channel.toUpperCase() : ''} thành công!`
  };
}

if (item.authorized && item.valid && !item.isDuplicate && item.sentSuccess && item.eventId) {
  try {
    const staticData = $getWorkflowStaticData('global');
    if (staticData) {
      staticData.processedEvents = staticData.processedEvents || {};
      staticData.processedEvents[item.eventId] = {
        status: 'success',
        timestamp: Date.now(),
        channel: item.channel,
        epicKey: item.epicKey
      };
    }
  } catch (e) {}
}

const payloadString = JSON.stringify(responsePayload);
return [{
  json: {
    step: 11,
    stepName: 'State & History Recorder',
    content: payloadString,
    ...responsePayload,
    _statusCode: finalStatusCode
  }
}];
